mapper.sql:
where 1=1

		and ccue_llave = #{llaveTabla}


		and ccue_estado = #{estado}


		and ccue_codigo = #{codigo}


		and ccue_nombre = #{nombre}


		and ccue_documento = #{documento}


		and dcue_fechaconciliacion >= #{fechaConciliacionMin}


		and dcue_fechaconciliacion  <   #{fechaConciliacionMax}


		and bcue_validarturno = #{validarTurnoFilter}


		and (upper(ccue_nombre) like upper('%' || #{filtroParametro} || '%'))
